[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "router-guide-surface",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "router-guide-surface",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "properties": {
            "children": [
              {
                "id": "header_text",
                "type": "Text",
                "properties": {
                  "text": "How to Change Linksys EA8300 SSID & WPA2 Password",
                  "style": "headline-medium",
                  "horizontalAlignment": "center"
                }
              },
              {
                "id": "prerequisites_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "prerequisites_column",
                    "type": "Column",
                    "properties": {
                      "children": [
                        {
                          "id": "assumptions_title",
                          "type": "Text",
                          "properties": {
                            "text": "Assumptions",
                            "style": "title-medium"
                          }
                        },
                        {
                          "id": "assumptions_text",
                          "type": "Text",
                          "properties": {
                            "text": "- You are currently connected to your Linksys EA8300 router.\n- You know the current administrative password for your router. If you don't, you may need to perform a factory reset."
                          }
                        },
                        {
                          "id": "divider_1",
                          "type": "Divider"
                        },
                        {
                          "id": "defaults_title",
                          "type": "Text",
                          "properties": {
                            "text": "Default Router Access Information",
                            "style": "title-medium"
                          }
                        },
                        {
                          "id": "defaults_text",
                          "type": "Text",
                          "properties": {
                            "text": "- **Local IP Address:** 192.168.1.1\n- **Username:** admin\n- **Password:** admin or password (or blank)\n\n*Always check the label on your router for the most accurate default login details.*"
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "steps_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "steps_column",
                    "type": "Column",
                    "properties": {
                      "children": [
                        {
                          "id": "steps_title",
                          "type": "Text",
                          "properties": {
                            "text": "Step-by-Step Guide",
                            "style": "headline-small"
                          }
                        },
                        {
                          "id": "steps_list",
                          "type": "List",
                          "properties": {
                            "children": [
                              {
                                "id": "step_1",
                                "type": "ListItem",
                                "properties": {
                                  "primary": "1. Access Your Router's Web Interface",
                                  "secondary": "Open a web browser and go to **192.168.1.1** in the address bar."
                                }
                              },
                              {
                                "id": "step_2",
                                "type": "ListItem",
                                "properties": {
                                  "primary": "2. Log In to Your Router",
                                  "secondary": "Enter the Username (typically \"admin\") and your current router administrative password, then click \"Log In\"."
                                }
                              },
                              {
                                "id": "step_3",
                                "type": "ListItem",
                                "properties": {
                                  "primary": "3. Navigate to Wireless Settings",
                                  "secondary": "Once logged in, look for a section like \"Wi-Fi Settings\", \"Wireless\", or \"Connectivity\"."
                                }
                              },
                              {
                                "id": "step_4",
                                "type": "ListItem",
                                "properties": {
                                  "primary": "4. Change the Wi-Fi Network Name (SSID)",
                                  "secondary": "In the Wireless settings, find the \"Network Name (SSID)\" field for the 2.4 GHz and 5 GHz bands. Enter your desired new Wi-Fi name."
                                }
                              },
                              {
                                "id": "step_5",
                                "type": "ListItem",
                                "properties": {
                                  "primary": "5. Change the Wi-Fi Password (WPA2 Security Key)",
                                  "secondary": "Ensure \"Security Mode\" is set to WPA2/WPA3 Personal. Find the \"Password\" or \"Passphrase\" field and enter your new, strong password (at least 8 characters with a mix of letters, numbers, and symbols)."
                                }
                              },
                              {
                                "id": "step_6",
                                "type": "ListItem",
                                "properties": {
                                  "primary": "6. Save Your Changes",
                                  "secondary": "Look for an \"Apply\", \"Save\", or \"OK\" button to save your new settings. The router may restart."
                                }
                              },
                              {
                                "id": "step_7",
                                "type": "ListItem",
                                "properties": {
                                  "primary": "7. Reconnect Your Devices",
                                  "secondary": "Your devices will be disconnected. On each device, find the new network name (SSID) and connect using your new password."
                                }
                              }
                            ]
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "note_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "note_row",
                    "type": "Row",
                    "properties": {
                      "children": [
                        {
                          "id": "note_icon",
                          "type": "Icon",
                          "properties": {
                            "icon": "info"
                          }
                        },
                        {
                          "id": "note_text",
                          "type": "Text",
                          "properties": {
                            "text": "**Important Note:** Always remember your new SSID and Wi-Fi password. It's a good idea to write them down and keep them in a secure place."
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "actions_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "actions_column",
                    "type": "Column",
                    "properties": {
                      "children": [
                        {
                          "id": "actions_title",
                          "type": "Text",
                          "properties": {
                            "text": "Quick Actions",
                            "style": "title-medium"
                          }
                        },
                        {
                          "id": "support_button",
                          "type": "Button",
                          "properties": {
                            "label": "Linksys EA8300 Support Page",
                            "action": {
                              "functionCall": {
                                "call": "openUrl",
                                "args": {
                                  "url": "https://www.linksys.com/us/support/products/routers/EA8300.html"
                                }
                              }
                            }
                          }
                        }
                      ]
                    }
                  }
                }
              },
              {
                "id": "sources_card",
                "type": "Card",
                "properties": {
                  "child": {
                    "id": "sources_column",
                    "type": "Column",
                    "properties": {
                      "children": [
                        {
                          "id": "sources_title",
                          "type": "Text",
                          "properties": {
                            "text": "Sources",
                            "style": "title-medium"
                          }
                        },
                        {
                          "id": "sources_text",
                          "type": "Text",
                          "properties": {
                            "text": "https://www.linksys.com/us/support/products/routers/EA8300.html"
                          }
                        }
                      ]
                    }
                  }
                }
              }
            ]
          }
        }
      ]
    }
  }
]
